package com.bank.tier;

import java.util.*;
import java.util.logging.*;

public class StreamOfDemo {
    private static final Logger log = Logger.getLogger("Tier");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        TierService service = new TierService();
        log.info(() -> "tiers       : " + service.tiers());
        log.info(() -> "lowercased  : " + service.lowerTiers());
    }
}

// ─── Would be in service/TierService.java ───
class TierService {
    List<String> tiers() {
        return java.util.stream.Stream.of("A", "B", "C")   // fixed finite stream
            .toList();
    }
    List<String> lowerTiers() {
        return java.util.stream.Stream.of("A", "B", "C")
            .map(String::toLowerCase)                        // pipeline on fixed values
            .toList();
    }
}
